.fxs .ds{--pushA:#F7EEF8;--pushB:#14507A;--pushC:#B9A6CF;--rim:#7FF0E2;--rimD:#14507A}
.fxs .push.ds{--pr:50px;background:none;border-radius:50px;box-shadow:none;filter:drop-shadow(0 8px 0 rgba(8,30,60,.5)) drop-shadow(0 18px 24px rgba(0,0,0,.4))}
