.fxs .pshadow.ds{width:230px}
.fxs .tap.ds{font-family:"Kiwi Maru",serif;font-weight:500;color:#BFF6EE;letter-spacing:.12em;text-shadow:0 2px 0 #0B2E52,0 0 10px rgba(127,240,226,.6)}
